import { implementService } from '@wix/services-definitions';
import { ProvideComponentServiceDefinition, } from './definition.js';
import { SignalsServiceDefinition } from '@wix/services-definitions/core-services/signals';
export const ProvideComponentServiceFactory = implementService(ProvideComponentServiceDefinition, ({ config, getService }) => {
    const { signal } = getService(SignalsServiceDefinition);
    const topComponents = signal(config.topComponents || []);
    const bottomComponents = signal(config.bottomComponents || []);
    const addTopComponent = (Comp) => {
        topComponents.set([...topComponents.get(), Comp]);
    };
    const addBottomComponent = (Comp) => {
        bottomComponents.set([...bottomComponents.get(), Comp]);
    };
    return {
        addTopComponent,
        addBottomComponent,
        getAllTopComponents: () => topComponents.get(),
        getAllBottomComponents: () => bottomComponents.get(),
    };
});
